using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using EfFixtures;

public static class PostQueries
{
    public static async Task<Dictionary<int, long>> GetTotalViewsPerBlogAsync(
        BlogContext context,
        string searchTerm,
        CancellationToken cancellationToken)
    {
        var query =
            from p in context.Posts
            where p.Title.Contains(searchTerm)
            group p by p.BlogId into g
            select new BlogViewTotal
            {
                BlogId = g.Key,
                TotalViews = g.Sum(x => (long)x.Views)
            };

        var totals = await query.ToListAsync(cancellationToken);

        return totals.ToDictionary(t => t.BlogId, t => t.TotalViews);
    }
}

public class BlogViewTotal
{
    public int BlogId { get; set; }
    public long TotalViews { get; set; }
}
